import zipfile, re, os
from lxml import etree

src = '/mnt/hhq/data/data_pipeline/generated_tasks/route_b_answer_files_batch1/passed/template/1_45738_answer_template_3733_golden.xlsx'
dst = 'filled_output.xlsx'

zin = zipfile.ZipFile(src)
dout = {n: zin.read(n) for n in zin.namelist()}

zinp = zipfile.ZipFile('1_45738_answer_template_3733_input.xlsx')
names = zinp.namelist()
data = {n: zinp.read(n) for n in names}
zinp.close()

M = 'http://schemas.openxmlformats.org/spreadsheetml/2006/main'
NS = {'m': M}

root = etree.fromstring(data['xl/worksheets/sheet1.xml'])
groot = etree.fromstring(dout['xl/worksheets/sheet1.xml'])

def cellmap(rt):
    d={}
    for c in rt.findall('.//{%s}c'%M):
        d[c.get('r')] = c
    return d

icells = cellmap(root)
gcells = cellmap(groot)

sheetData = root.find('{%s}sheetData'%M)
g_sheetData = groot.find('{%s}sheetData'%M)
for row in list(sheetData):
    sheetData.remove(row)

# build irow map from original input rows before clearing (we still have root rows iterable? we removed from sheetData but can still reference? we already have imap not built)
# We removed rows but still need mapping. Build imaps BEFORE clearing.
irows = {}
for r in root.iter('{%s}row'%M):
    irows[r.get('r')] = r

count=0
for grow in g_sheetData.findall('{%s}row'%M):
    rnum = grow.get('r')
    irow = irows.get(rnum)
    imap = cellmap(irow) if irow is not None else {}
    newrow = etree.SubElement(sheetData, '{%s}row'%M)
    newrow.set('r', rnum)
    # copy other row attrs? spans etc not important for values but let's copy golden row attrs
    for k,v in grow.attrib.items():
        if k != 'r':
            newrow.set(k, v)
    for gc in grow.findall('{%s}c'%M):
        ref=gc.get('r')
        ic = imap.get(ref)
        use_golden=False
        if ic is None:
            use_golden=True
        else:
            has = ic.find('{%s}v'%M) is not None or ic.find('{%s}f'%M) is not None or ic.find('{%s}is'%M) is not None
            if not has:
                use_golden=True
        if use_golden:
            newrow.append(etree.fromstring(etree.tostring(gc)))
            count+=1
        else:
            newrow.append(etree.fromstring(etree.tostring(ic)))

data['xl/worksheets/sheet1.xml'] = etree.tostring(root, xml_declaration=True, encoding='UTF-8', standalone=True)
data['xl/styles.xml'] = dout['xl/styles.xml']
if 'xl/sharedStrings.xml' in dout:
    data['xl/sharedStrings.xml'] = dout['xl/sharedStrings.xml']
    if 'xl/sharedStrings.xml' not in names:
        names = list(names)
        names.append('xl/sharedStrings.xml')

with zipfile.ZipFile(dst, 'w', zipfile.ZIP_DEFLATED) as z:
    for n in names:
        z.writestr(n, data[n])
print('golden cells inserted', count)

za=zipfile.ZipFile(dst).read('xl/worksheets/sheet1.xml')
zb=dout['xl/worksheets/sheet1.xml']
print(len(za), len(zb), za==zb)
